import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "dialogId", label: "Dialog ID", value: "my-dialog" })}${field({ id: "dialogTitle", label: "Dialog title", value: "Dialog Title" })}${textarea({ id: "dialogContent", label: "Dialog content (HTML)", value: "<p>Dialog content goes here.</p>" })}${field({ id: "dialogButton", label: "Open button text", value: "Open Dialog" })}${field({ id: "dialogCloseButton", label: "Close button text", value: "Close" })}</div><div class="check-grid">${checkbox({ id: "dialogModal", label: "Use showModal() (with backdrop)", checked: true })}${checkbox({ id: "dialogAutoClose", label: "Close on backdrop click" })}</div>`,generate(root) {const id = root.querySelector("#dialogId").value.trim() || "my-dialog";const title = root.querySelector("#dialogTitle").value.trim() || "Dialog Title";const content = root.querySelector("#dialogContent").value.trim();const buttonText = root.querySelector("#dialogButton").value.trim() || "Open Dialog";const closeText = root.querySelector("#dialogCloseButton").value.trim() || "Close";const modal = root.querySelector("#dialogModal").checked;const autoClose = root.querySelector("#dialogAutoClose").checked;const openFn = modal ? "showModal()" : "show()";const autoCloseAttr = autoClose ? ` onclick="if(event.target===this)this.close()"` : "";const output = `<button id="${id}-open">${htmlEscape(buttonText)}</button><dialog id="${attrEscape(id)}"${autoCloseAttr}><h2>${htmlEscape(title)}</h2>${content}<button id="${id}-close">${htmlEscape(closeText)}</button></dialog><script>document.getElementById('${id}-open').addEventListener('click',function(){document.getElementById('${id}').${openFn};});document.getElementById('${id}-close').addEventListener('click',function(){document.getElementById('${id}').close();});<\/script><style>dialog {padding: 1.5rem;border: 1px solid #e5e7eb;border-radius: 8px;max-width: 500px;width: 90%;}dialog::backdrop {background: rgba(0,0,0,0.4);}<\/style>`;return { output };}};